# current functionality allows an admin to toggle the available databases
# the list of databases to enable/disable is store in a property until the admin selects 'Save'
# based on that list, this function will attempt to enable/disable each one
# enable means there is a matching configs table and the first row has private=0
# disabled means the first row has private=1, or there is no matching configs table 
# for enable: this will check for valid connection, create configs table if necessary, or update the existing matching table with private=0
# for disable: this will check for valid connection, update the existing matching table with private=1
# after doing this, we send out a message to open sessions to update their db listing, so they don't have to manually refresh anything

logger = system.util.getLogger('Ad Hoc Trends')
for dbDetailedName in self.view.custom.configureDatabases:
	dbInfo = next((d for d in self.view.custom.databases if '%s:%s' %(d.connector, d.Name) == dbDetailedName), False)
	if not dbInfo:
		logger.error('Unable to create configuration table for database "%s" because it was not found in database list (view.custom.databases).' %dbDetailedName)
		continue

	if dbInfo['Status'] != "Valid":
		logger.error('Unable to create configuration table for database "%s" because database does not have a valid connection.' %dbDetailedName)
		continue

	dbEnable = self.view.custom.configureDatabases[dbDetailedName]
	if dbInfo['connector'] == 'sql':
		dbType = dbInfo['DBType']

		tableExistsQuery = self.view.rootContainer.getTableExistsQuery(dbType)
		tableFormatMatchesQuery = self.view.rootContainer.getTableFormatMatchesQuery(dbType)
		createTableQuery = self.view.rootContainer.getCreateTableQuery(dbType)
		makeDatabasePrivateQuery = self.view.rootContainer.getMakeDatabasePrivateQuery(dbType)

		if not tableExistsQuery or not tableFormatMatchesQuery or not createTableQuery or not makeDatabasePrivateQuery:
			logger.error('Unable to create configuration table for sql database "%s" because it is an unknown database type "%s".' %(dbInfo['Name'], dbType))
			continue

		tableExists = system.db.runScalarPrepQuery(tableExistsQuery, None, dbInfo['Name'])

		if dbEnable:
			if tableExists:
				tableFormatMatches = system.db.runScalarPrepQuery(tableFormatMatchesQuery, None, dbInfo['Name'])
				if tableFormatMatches:
					system.db.runPrepUpdate(makeDatabasePrivateQuery, [False, False], dbInfo['Name'])
					logger.info('Enabled sql database "%s"' %dbInfo['Name'])
				else:
					logger.error('Unable to create configuration table for sql database "%s" because configuration table but does not match expected format [id,user,public,config, config_name,timestamp].' %dbInfo['Name'])
			else:
				system.db.runPrepUpdate(createTableQuery, None, dbInfo['Name'])
				logger.info('Created configuration table for sql database "%s"' %dbInfo['Name'])
				system.db.runPrepUpdate(makeDatabasePrivateQuery, [False, False], dbInfo['Name'])
				logger.info('Enabled sql database "%s"' %dbInfo['Name'])
		else:
			if tableExists:
				tableFormatMatches = system.db.runScalarPrepQuery(tableFormatMatchesQuery, None, dbInfo['Name'])
				if tableFormatMatches:
					system.db.runPrepUpdate(makeDatabasePrivateQuery, [True, True], dbInfo['Name'])
					logger.info('Disabled sql database "%s"' %dbInfo['Name'])
				else:
					logger.error('Unable to create configuration table for sql database "%s" because configuration table but does not match expected format [id,user,public,config, config_name,timestamp].' %dbInfo['Name'])
			else:
				# ad hoc trends config table does not exist, so there is no change needed
				pass
	elif dbInfo['connector'] == 'mongodb':
		# collection exists
		# upsert
		if dbEnable:
			system.mongodb.updateOne(dbInfo['Name'], 'ad_hoc_trends_config', {'_id': 'config'}, {'$set': {'Enabled': True}}, {'upsert': True})
		else:
			system.mongodb.updateOne(dbInfo['Name'], 'ad_hoc_trends_config', {'_id': 'config'}, {'$set': {'Enabled': False}}, {'upsert': True})


